test("a 40 by 30 by 20 cm parcel at 3.2 kg uses rounded weights and bills 5.0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 40, widthCm: 30, heightCm: 20, actualWeightKg: 3.2 }), {
    dimensionalWeightKg: 4.8,
    roundedDimensionalWeightKg: 5.0,
    roundedActualWeightKg: 3.5,
    billableWeightKg: 5.0
  });
});

test("a 10 by 10 by 10 cm parcel at 2.0 kg keeps the exact actual weight and bills 2.0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 2.0 }), {
    dimensionalWeightKg: 0.2,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 2.0,
    billableWeightKg: 2.0
  });
});

test("equal weights already on a 0.5 boundary stay 0.5 and bill 0.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 25, widthCm: 10, heightCm: 10, actualWeightKg: 0.5 }), {
    dimensionalWeightKg: 0.5,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.5,
    billableWeightKg: 0.5
  });
});

test("dimensional weight one step below 0.5 rounds up to 0.5 not 1.0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 2499, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.4998,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0,
    billableWeightKg: 0.5
  });
});

test("dimensional weight one step above 0.5 rounds up to 1.0 not 0.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 2501, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.5002,
    roundedDimensionalWeightKg: 1.0,
    roundedActualWeightKg: 0,
    billableWeightKg: 1.0
  });
});

test("zero volume and zero weight stay zero and bill zero", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 0, widthCm: 0, heightCm: 0, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0,
    roundedDimensionalWeightKg: 0,
    roundedActualWeightKg: 0,
    billableWeightKg: 0
  });
});

test("one cubic centimetre rounds dimensional weight up to 0.5 and bills 0.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 1, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.0002,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0,
    billableWeightKg: 0.5
  });
});

test("dimensional weight of exactly 0.25 rounds up to 0.5 not 0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 25, widthCm: 10, heightCm: 5, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.25,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0,
    billableWeightKg: 0.5
  });
});

test("dimensional weight one step below 0.25 still rounds up to 0.5 not 0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 1249, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.2498,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0,
    billableWeightKg: 0.5
  });
});

test("dimensional weight one step above 0.25 rounds up to 0.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 1251, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.2502,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0,
    billableWeightKg: 0.5
  });
});

test("dimensional weight one step below 0.75 rounds up to 1.0 not 0.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 3749, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.7498,
    roundedDimensionalWeightKg: 1.0,
    roundedActualWeightKg: 0,
    billableWeightKg: 1.0
  });
});

test("dimensional weight of exactly 0.75 rounds up to 1.0 not 0.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 15, widthCm: 25, heightCm: 10, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.75,
    roundedDimensionalWeightKg: 1.0,
    roundedActualWeightKg: 0,
    billableWeightKg: 1.0
  });
});

test("dimensional weight one step above 0.75 rounds up to 1.0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 3751, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.7502,
    roundedDimensionalWeightKg: 1.0,
    roundedActualWeightKg: 0,
    billableWeightKg: 1.0
  });
});

test("actual weight one step below 0.5 rounds up to 0.5 not 1.0", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 1, actualWeightKg: 0.4998 }), {
    dimensionalWeightKg: 0.0002,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.5,
    billableWeightKg: 0.5
  });
});

test("actual weight 2.1 rounds up to 2.5 and that rounded value is billed", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 2.1 }), {
    dimensionalWeightKg: 0.2,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 2.5,
    billableWeightKg: 2.5
  });
});

test("an exact multiple written as 3 stays 3 and is not raised to 3.5", function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 3, widthCm: 3.0, heightCm: 1, actualWeightKg: 3 }), {
    dimensionalWeightKg: 0.0018,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 3,
    billableWeightKg: 3
  });
});
